import dynamic from 'next/dynamic';
import { tier } from '@chaff/tier';
import { StagePoster } from './StagePoster';

const LazyWebGLCanvas = dynamic(() => import('./StageWebGL'), { ssr: false, loading: () => <StagePoster /> });

export function HeroScene() {
  const deviceTier = tier();
  if (deviceTier === 'poster') return <StagePoster />;
  return (
    <div className="w-full min-h-dvh relative">
      <LazyWebGLCanvas deviceTier={deviceTier} maxPixelRatio={1.5} />
    </div>
  );
}
